import c from "config";
import { formatInTimeZone } from "date-fns-tz";
import manifestsJson from "./manifests.json";
import { presentationEntries, type PresentationEntry } from "./data";

export * from "./data";
export * from "./paths";

/** Generated by scripts/presentations/render_slides.py. */
export interface SlideDeck {
	slideCount: number;
	width: number;
	height: number;
	pdfBytes: number;
	/** Text pulled from each slide's PDF text layer (may be empty). */
	text: string[];
}

export interface Presentation extends PresentationEntry {
	deck: SlideDeck | null;
}

const manifests = manifestsJson as Record<string, SlideDeck>;

/** Every presentation, in schedule order. */
export const presentations: Presentation[] = presentationEntries
	.map((entry) => ({ ...entry, deck: manifests[entry.slug] ?? null }))
	.sort(
		(a, b) =>
			Date.parse(a.start) - Date.parse(b.start) ||
			a.title.localeCompare(b.title),
	);

export function getPresentation(slug: string): Presentation | undefined {
	return presentations.find((p) => p.slug === slug);
}

export function getPresentationForEvent(
	eventId: number,
): Presentation | undefined {
	return presentations.find((p) => p.eventId === eventId);
}

const tz = c.hackathonTimezone;

/** "8:30 – 9:00 AM", or "11:30 AM – 12:30 PM" when the period changes. */
export function formatTimeRange(p: Pick<PresentationEntry, "start" | "end">) {
	const start = new Date(p.start);
	const end = new Date(p.end);
	const samePeriod =
		formatInTimeZone(start, tz, "a") === formatInTimeZone(end, tz, "a");
	return samePeriod
		? `${formatInTimeZone(start, tz, "h:mm")} – ${formatInTimeZone(end, tz, "h:mm a")}`
		: `${formatInTimeZone(start, tz, "h:mm a")} – ${formatInTimeZone(end, tz, "h:mm a")}`;
}

/** "Saturday, November 7, 2026" */
export function formatDay(p: Pick<PresentationEntry, "start">) {
	return formatInTimeZone(new Date(p.start), tz, "EEEE, MMMM d, yyyy");
}

export function formatBytes(bytes: number) {
	if (bytes < 1024 * 1024)
		return `${Math.max(1, Math.round(bytes / 1024))} KB`;
	return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

export function formatSpeakers(speakers: string[]) {
	if (speakers.length <= 2) return speakers.join(" & ");
	return `${speakers.slice(0, -1).join(", ")} & ${speakers[speakers.length - 1]}`;
}

export type DescriptionBlock =
	{ kind: "paragraph"; text: string } | { kind: "list"; items: string[] };

/** Splits an abstract into paragraphs and "- " bullet lists. */
export function parseDescription(description: string): DescriptionBlock[] {
	return description
		.split(/\n\s*\n/)
		.map((block) => block.trim())
		.filter(Boolean)
		.map((block): DescriptionBlock => {
			const lines = block.split("\n").map((l) => l.trim());
			if (lines.every((l) => l.startsWith("- "))) {
				return { kind: "list", items: lines.map((l) => l.slice(2)) };
			}
			return { kind: "paragraph", text: lines.join(" ") };
		});
}
